function a(){const e=document.querySelectorAll(".tab-button"),t=document.querySelectorAll(".panel");e.forEach(c=>{c.addEventListener("click",()=>{e.forEach(o=>o.classList.remove("active")),t.forEach(o=>o.classList.remove("active")),c.classList.add("active"),document.getElementById(c.dataset.tab).classList.add("active")})})}function d(){document.querySelectorAll(".code-button").forEach(e=>{e.addEventListener("click",()=>{const t=document.getElementById(e.dataset.code);t.hidden=!t.hidden,e.textContent=t.hidden?"Show code":"Hide code"})})}function s(){document.querySelectorAll(".copy-button").forEach(e=>{e.addEventListener("click",async()=>{await navigator.clipboard.writeText(e.dataset.copy),e.classList.add("copied"),clearTimeout(e.copiedTimer),e.copiedTimer=setTimeout(()=>e.classList.remove("copied"),1200)})})}function n(){document.querySelectorAll(".open-button").forEach(e=>{e.addEventListener("click",()=>{const t=document.getElementById(e.dataset.link).href;t&&window.open(t,"_blank","noopener")})})}export{d as a,s as b,n as c,a as s};
